<style>
:root{--paper:#f8f9f2;--white:#fff;--ink:#183e36;--muted:#5f7168;--line:#dce2d7;--green:#c8eab4;--blue:#d9eef5;--blue-ink:#367f96;--warm:#eeeee1;--surface:#f7f9f5;--radius:24px;--font:'DM Sans',sans-serif;--display:'Manrope',sans-serif;--ease:180ms ease-out;--space-section:96px}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:32px}body{margin:0;background:var(--paper);color:var(--ink);font-family:var(--font);font-size:16px;line-height:1.55;-webkit-font-smoothing:antialiased}button,a,input{ -webkit-tap-highlight-color:transparent}a{color:inherit;text-decoration:none}button,input{font:inherit}button{cursor:pointer}button,a{touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--blue-ink);outline-offset:5px}button{color:inherit}svg{display:block}h1,h2,h3,p{margin:0}h1,h2,h3{font-family:var(--display);text-wrap:balance}p{text-wrap:pretty}.container{width:min(1248px,calc(100% - 96px));margin-inline:auto}.skip{position:fixed;top:-100px;left:16px;background:var(--ink);color:white;padding:12px 24px;z-index:20}.skip:focus{top:16px}.site-header{height:108px;display:flex;align-items:center;justify-content:space-between;gap:32px}.brand{display:inline-flex;align-items:center;gap:10px;font-family:var(--display);font-size:29px;font-weight:800;letter-spacing:-1.5px;line-height:1}.brand svg{width:37px;height:35px}.nav-links{display:flex;gap:36px;align-items:center;font-size:14px;font-weight:500}.nav-links a{position:relative;padding-block:12px}.nav-links a:after{content:'';position:absolute;bottom:7px;left:0;width:0;height:1px;background:currentColor;transition:width var(--ease)}.nav-links a:hover:after{width:100%}.btn{display:inline-flex;justify-content:center;align-items:center;gap:28px;min-height:52px;padding:14px 24px;border:1px solid transparent;border-radius:8px;background:var(--ink);color:var(--paper);font-size:14px;font-weight:550;line-height:1.3;transition:background var(--ease),transform var(--ease)}.btn:hover{background:#2c594c;transform:translateY(-2px)}.btn:active{transform:translateY(0)}.btn svg{width:17px;height:17px}.btn.light{background:var(--green);color:var(--ink)}.btn.light:hover{background:#d6f0c7}.site-header>.btn{min-height:44px;padding:12px 18px;gap:24px}.menu-toggle{display:none;background:none;border:0;padding:12px}.hero{display:grid;grid-template-columns:.93fr 1.07fr;align-items:center;gap:56px;padding-top:48px;padding-bottom:80px}.eyebrow{display:flex;align-items:center;gap:8px;font-size:12px;font-weight:600;letter-spacing:1.4px;text-transform:uppercase;margin-bottom:24px}.eyebrow:before{content:'';width:7px;height:7px;background:var(--blue-ink);border-radius:50%}h1{font-size:clamp(50px,5.2vw,74px);font-weight:650;line-height:1.075;letter-spacing:-4px;margin-left:-3px;max-width:650px}h1 span{color:var(--blue-ink)}.hero-copy>p{max-width:405px;color:var(--muted);font-size:17px;line-height:1.7;margin-top:24px}.hero-actions{display:flex;gap:24px;align-items:center;margin-top:32px}.text-button{display:inline-flex;align-items:center;gap:8px;background:none;border:0;padding:12px 0;font-size:14px;font-weight:550}.play{display:inline-flex;width:25px;height:25px;align-items:center;justify-content:center;border:1px solid var(--ink);border-radius:50%;font-size:9px}.text-button:hover{text-decoration:underline;text-underline-offset:4px}.hero-notes{margin-top:32px;display:flex;gap:20px;font-size:12px;color:var(--muted)}.hero-notes span{display:flex;align-items:center;gap:6px}.hero-notes svg{width:13px;height:13px;stroke:var(--ink)}
/* A small gym, seen through Tidepool. The illustration and UI stay in one frame. */
.hero-art{height:518px;position:relative;border-radius:120px 24px 24px 24px;background:#dfece6;isolation:isolate;display:flex;align-items:center;justify-content:center;padding:32px 24px;min-width:0}.wall-art{position:absolute;inset:0;z-index:-1;width:100%;height:100%;border-radius:inherit;overflow:hidden}.art-topline{position:absolute;left:36px;top:24px;font-size:10px;font-weight:600;letter-spacing:1.6px;text-transform:uppercase;color:#426358}.art-topline span{display:inline-block;width:5px;height:5px;margin-right:6px;vertical-align:2px;border-radius:50%;background:#426358}.app{width:100%;margin-top:18px;min-height:347px;background:#fff;border:5px solid rgba(255,255,255,.55);border-radius:12px;box-shadow:0 16px 32px #1b443c13;overflow:hidden;font-size:10px}.app-top{height:43px;padding:0 15px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #eaf0e9;background:#fff}.mini-brand{display:flex;align-items:center;gap:6px;font-family:var(--display);font-weight:800;font-size:15px;letter-spacing:-.7px}.mini-brand svg{width:22px;height:22px}.workspace-name{font-size:9px;color:var(--muted);display:flex;align-items:center;gap:6px}.workspace-name:before{content:'P';display:grid;place-items:center;width:20px;height:20px;border-radius:5px;background:var(--warm);font-size:10px;font-weight:700}.app-body{display:grid;grid-template-columns:106px 1fr;min-height:295px}.app-sidebar{padding:16px 8px;background:#f7f9f5;border-right:1px solid #eaf0e9;display:flex;flex-direction:column;gap:4px}.app-tab{display:flex;align-items:center;gap:7px;border:0;background:transparent;font-size:9px;text-align:left;min-height:32px;padding:7px;border-radius:5px;color:#65756b;white-space:nowrap}.app-tab svg{width:13px;height:13px;flex-shrink:0}.app-tab.active{background:#e2eddd;color:var(--ink);font-weight:600}.app-tab:hover{background:#e9eee5}.app-side-bottom{margin-top:auto;padding:12px 6px 0;font-size:8px;display:flex;align-items:center;gap:5px;color:#6c7c70}.app-side-bottom:before{content:'';width:5px;height:5px;background:#6e8963;border-radius:50%}.app-main{padding:19px 16px 14px;min-width:0}.app-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;margin-bottom:15px}.app-heading h3{font-size:17px;font-weight:700;letter-spacing:-.6px;line-height:1.4}.app-heading p{font-size:8px;color:var(--muted);margin-top:1px}.mini-date{font-size:8px;white-space:nowrap;background:var(--surface);padding:5px 7px;border:1px solid #e7ebe3;border-radius:4px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:18px}.stat{padding:10px 9px;border:1px solid #e6ebe2;border-radius:6px}.stat-label{font-size:8px;color:#647268;white-space:nowrap}.stat strong{display:block;margin-top:4px;font-family:var(--display);font-weight:650;font-size:23px;line-height:1.2;letter-spacing:-.5px}.stat small{display:block;margin-top:5px;font-size:7px;color:#54754a}.stat:last-child{background:#eef5e8;border-color:#eef5e8}.app-section-head{display:flex;justify-content:space-between;align-items:center;font-size:10px;font-weight:600;margin-bottom:8px}.app-section-head span{font-size:8px;font-weight:400;color:var(--muted)}.class-row{display:flex;gap:9px;align-items:center;padding:9px 0;border-top:1px solid #edf0e9}.class-icon{width:27px;height:29px;border-radius:5px;display:grid;place-items:center;background:#edf2e7;flex-shrink:0}.class-icon.blue{background:#e3eff6}.class-icon svg{width:15px;height:15px}.class-name{flex:1;font-size:9px;font-weight:600}.class-name small{display:block;color:var(--muted);font-size:8px;font-weight:400;margin-top:2px}.class-spots{font-size:8px;color:var(--muted);white-space:nowrap}.capacity{height:3px;background:#ebf0e7;width:45px;border-radius:3px;margin-top:4px}.capacity:before{content:'';display:block;width:75%;height:100%;background:#a8c88d;border-radius:3px}.class-row:last-child .capacity:before{width:45%;background:#95bfcc}.art-caption{position:absolute;bottom:23px;left:32px;right:32px;display