.toolkit{padding-top:88px;padding-bottom:88px}.section-intro{display:flex;justify-content:space-between;align-items:end;gap:48px;margin-bottom:40px}h2{font-size:42px;line-height:1.17;letter-spacing:-1.8px;font-weight:600}.section-intro p{max-width:330px;color:var(--muted);font-size:15px;margin-bottom:3px}.feature-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:24px}.feature{padding:28px 28px 24px;background:#eeefe3;border-radius:16px;overflow:hidden;display:flex;flex-direction:column;align-items:flex-start}.feature:nth-child(2){background:#e5eef0}.feature:nth-child(3){background:#e7eddf}.feature-top{display:flex;justify-content:space-between;width:100%;align-items:center;margin-bottom:24px}.feature-top svg{width:28px;height:28px}.feature-number{font-size:11px;letter-spacing:1px;color:var(--muted)}.feature h3{font-size:22px;font-weight:650;letter-spacing:-.6px;margin-bottom:10px}.feature>p{font-size:14px;color:#58685d;line-height:1.65;max-width:30ch}.feature-visual{height:143px;width:100%;margin-top:28px;display:flex;align-items:center;justify-content:center}.member-pass{background:#fafbf6;border-radius:9px;width:100%;max-width:280px;padding:17px 18px;transform:rotate(-4deg);box-shadow:0 7px 16px #223c2410}.pass-top{display:flex;justify-content:space-between;align-items:center;font-size:10px;color:var(--muted);margin-bottom:12px}.status-pill{font-size:9px;background:#e0edce;color:#3b5e30;border-radius:4px;padding:3px 7px}.member-details{display:flex;align-items:center;gap:10px}.avatar{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;background:#e2e8d5;color:#567043;font-size:12px}.member-details strong{font-size:13px;font-weight:600}.member-details small{display:block;font-size:10px;color:var(--muted);margin-top:1px}.pass-dots{margin-left:auto;display:flex;align-items:center;gap:2px}.pass-dots i{display:block;width:2px;height:23px;background:#4b5c48}.pass-dots i:nth-child(2n){width:3px;height:23px}.mini-booking{background:#fff;border