.gym-section{padding:0 0 88px}.gym-panel{display:grid;grid-template-columns:1fr 1fr;min-height:366px;border-radius:var(--radius);overflow:hidden;background:#e2ece2}.gym-illustration{position:relative;overflow:hidden;min-height:340px}.gym-illustration>svg{width:100%;height:100%;position:absolute;inset:0}.gym-copy{padding:56px 48px 48px 40px;align-self:center}.gym-copy h2{font-size:36px;max-width:370px}.gym-copy p{margin-top:20px;color:var(--muted);font-size:15px;max-width:360px}.gym-copy .text-button{margin-top:16px;gap:24px}.bottom-cta{background:var(--ink);color:var(--paper);border-radius:var(--radius);padding:48px 56px;display:flex;align-items:center;justify-content:space-between;gap:32px;margin-bottom:56px}.bottom-cta h2{font-size:34px;letter-spacing:-1.2px}.bottom-cta p{color:#bfd0c3;font-size:14px;margin-top:10px}.bottom-cta .btn{flex-shrink:0}.site-footer{display:flex;align-items:center;justify-content:space-between;gap:24px;border-top:1px solid var(--line);padding:28px 0 32px}.site-footer .brand{font-size:23px}.site-footer .brand svg{width:30px;height:28px}.footer-right{display:flex;align-items:center;gap:32px;font-size:12px;color:var(--muted)}.footer-right a{padding:12px 0}.footer-right a:hover{text-decoration:underline}.footer-copy{font-size:11px;color:var(--muted)}
/* Tour is deliberately local: all records are clearly identified as sample data. */
dialog{width:min(620px,calc(100% - 32px));padding:0;border:0;border-radius:20px;background:var(--paper);color:var(--ink);box-shadow:0 24px 100px #102b3540}dialog::backdrop{background:#143c32a6;backdrop-filter:blur(5px)}.tour-top{padding:24px 28px 0;display:flex;justify-content:space-between;align-items:center}.tour-label{font-size:11px;text-transform:uppercase;letter-spacing:1.4px;color:var(--muted)}.close-dialog{border:0;background:#e8eddf;border-radius:50%;width:44px;height:44px;font-size:25px;line-height:1}.close-dialog:hover{background:#dae5cd}.tour-content{padding:8px 36px 32px}.tour-content h2{font-size:32px;margin:12px 0}.tour-content>p{font-size:15px;color:var(--muted);max-width:460px}.tour-example{margin-top:24px;padding:24px;background:#fff;border:1px solid var(--line);border-radius:12px;min-height:180px}.tour-example .member-details strong{font-size:16px}.tour-example .member-details small{font-size:13px}.tour-example .avatar{width:44px;height:44px;font-size:14px}.tour-example .example-info{font-size:13px;color:var(--muted);margin:20px 0 16px}.tour-example .btn{font-size:12px;min-height:44px;padding:10px 16px}.tour-actions{display:flex;align-items:center;justify-content:space-between;margin-top:24px}.tour-dots{display:flex;gap:8px}.tour-dots button{width:32px;height:32px;padding:0;border:0;background:transparent;display:grid;place-items:center}.tour-dots button:before{content:'';width:7px;height:7px;background:#c5d1c1;border-radius:50%}.tour-dots button.active:before{background:var(--ink)}.tour-feedback{font-size:13px;color:#3c6349;display:flex;align-items:center;gap:8px;margin-top:14px}.tour-feedback svg{width:17px;height:17px}.tour-footnote{font-size:11px;color:var(--muted);margin-top:20px}.tour-class{display:flex;align-items:center;justify-content:space-between;gap:12px}.tour-class strong{font-size:16px}.tour-class small{display:block;font-size:13px;color:var(--muted);margin-top:4px}.tour-seat{background:#e4efd9;color:#3b5e30;font-size:11px;padding:5px